/* cppi::b2143e7441fc4a45ffcf0d4dc5d3f702265a8ad4df9947a2be45a444bb58b356 */
select index_id, time_key, currency_code, geography, country_name, index_value, source_file
from (
        select *, max(last_publish) over (partition by index_id, time_key) max_publish
            from market.tfm_gdp_index
            where time_key between 1984 and 2030
            and last_publish <= date '2025-04-01'
    ) a
where last_publish = max_publish

/* cppi::d95e209c536126a9af610a0fdd4634fe9e0bda240b416b2208b1d09de62762bb */
select business_date as date_, security_id, id_vendor_security_eod, id_vendor_security_ndo, bloomberg_ticker, id_sedol_eod, id_sedol_ndo, weight_eod, weight_ndo, country_listing
 from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, 
                id_vendor_security_ndo order by feed_version asc, id_cppib_index desc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                where business_date = date '2025-06-19'

